# check for duplicates
seen = set()
for conf in conf_list:
    conf_tuple = tuple(sorted(conf.items()))
    if conf_tuple in seen:
        print("Duplicate found:", conf)
    else:
        seen.add(conf_tuple)

# # flop count
total_flops = 0
for conf in conf_list:
    flops = flops_estimator(**conf)
    params = parameters_estimator(**conf)
    ratio = aspect_ratio_fn(**conf)
    total_flops += flops
    print(f"Config: {conf}, ratio {ratio:3f} Flops: {flops:e}, Parameters: {params:e} Data {seen_datapoints_estimator(**conf):e}")
print(len(conf_list))
print(f"Total Flops: {total_flops:e}")
